package main

import (
    "encoding/json"
    "fmt"
    "log"

    "github.com/pilot-protocol/common/driver"
    "github.com/pilot-protocol/common/protocol"
    "github.com/pilot-protocol/eventstream"
)

// Subscriber: replaces your webhook endpoint
func main() {
    d, err := driver.Connect("")
    if err != nil {
        log.Fatal(err)
    }
    defer d.Close()

    // The peer whose daemon carries the stream (port 1002)
    broker, err := protocol.ParseAddr("0:0000.0000.0005")
    if err != nil {
        log.Fatal(err)
    }

    // Topics match exactly; "*" receives every topic (replaces a Stripe webhook)
    sub, err := eventstream.Subscribe(d, broker, "*")
    if err != nil {
        log.Fatal(err)
    }
    defer sub.Close()

    fmt.Println("Listening for payment events...")
    for {
        event, err := sub.Recv()
        if err != nil {
            log.Fatal(err)
        }
        var payload map[string]any
        json.Unmarshal(event.Payload, &payload)
        fmt.Printf("[%s] %v\n", event.Topic, payload)

        // Process the event
        switch event.Topic {
        case "payments.completed":
            handlePaymentComplete(payload)
        case "payments.failed":
            handlePaymentFailed(payload)
        case "payments.refunded":
            handleRefund(payload)
        }
    }
}

package main

import (
    "encoding/json"
    "log"
    "time"

    "github.com/pilot-protocol/common/driver"
    "github.com/pilot-protocol/common/protocol"
    "github.com/pilot-protocol/eventstream"
)

// Publisher: replaces the webhook sender
func main() {
    d, err := driver.Connect("")
    if err != nil {
        log.Fatal(err)
    }
    defer d.Close()

    broker, err := protocol.ParseAddr("0:0000.0000.0005")
    if err != nil {
        log.Fatal(err)
    }

    // The broker protocol subscribes first, then publishes on the same stream
    pub, err := eventstream.Subscribe(d, broker, "payments.completed")
    if err != nil {
        log.Fatal(err)
    }
    defer pub.Close()

    event := map[string]any{
        "payment_id": "pay_abc123",
        "amount":     9900,
        "currency":   "usd",
        "status":     "completed",
        "ts":         time.Now().Unix(),
    }
    data, _ := json.Marshal(event)
    if err := pub.Publish("payments.completed", data); err != nil {
        log.Fatal(err)
    }
}
